CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle used in URLs and in @mentions. 39 chars matches what the product actually allows, and it is compared case-insensitively.
	"login" VARCHAR(39) NOT NULL UNIQUE,
	-- Primary account address. Commits carry their own author email, because git does not ask permission before recording one.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Optional real name shown beside the login.
	"display_name" VARCHAR(120),
	-- Where the profile image lives. A URL, not bytes: images belong in object storage.
	"avatar_url" TEXT,
	-- Staff flag. Kept here rather than in a role table because it is a single global bit, not a scoped permission.
	"is_site_admin" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Set when an account is disabled. The row is never deleted: every commit, issue and review in the system points at it.
	"suspended_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person. Accounts are soft-suspended rather than removed, because deleting a user would orphan a decade of authorship across every repository they ever touched.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."login" IS 'Public handle used in URLs and in @mentions. 39 chars matches what the product actually allows, and it is compared case-insensitively.';
COMMENT ON COLUMN "users"."email" IS 'Primary account address. Commits carry their own author email, because git does not ask permission before recording one.';
COMMENT ON COLUMN "users"."display_name" IS 'Optional real name shown beside the login.';
COMMENT ON COLUMN "users"."avatar_url" IS 'Where the profile image lives. A URL, not bytes: images belong in object storage.';
COMMENT ON COLUMN "users"."is_site_admin" IS 'Staff flag. Kept here rather than in a role table because it is a single global bit, not a scoped permission.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';
COMMENT ON COLUMN "users"."suspended_at" IS 'Set when an account is disabled. The row is never deleted: every commit, issue and review in the system points at it.';

CREATE TABLE IF NOT EXISTS "organizations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Organisation handle. Shares a namespace with user logins, which is why one uniqueness rule has to cover both in practice.
	"login" VARCHAR(39) NOT NULL UNIQUE,
	-- Human-readable name, e.g. Acme Robotics.
	"display_name" VARCHAR(160),
	-- Founding owner. A denormalised convenience so an org always has one accountable human even while the membership table is being reorganised.
	"owner_user_id" BIGINT NOT NULL,
	-- Where invoices go. Separate from any member address, because finance outlives employment.
	"billing_email" VARCHAR(320) NOT NULL,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "organizations" IS 'An account that owns repositories on behalf of a group. Membership and teams are deliberately out of scope here; the interesting modelling in this schema is downstream of ownership.';
COMMENT ON COLUMN "organizations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "organizations"."login" IS 'Organisation handle. Shares a namespace with user logins, which is why one uniqueness rule has to cover both in practice.';
COMMENT ON COLUMN "organizations"."display_name" IS 'Human-readable name, e.g. Acme Robotics.';
COMMENT ON COLUMN "organizations"."owner_user_id" IS 'Founding owner. A denormalised convenience so an org always has one accountable human even while the membership table is being reorganised.';
COMMENT ON COLUMN "organizations"."billing_email" IS 'Where invoices go. Separate from any member address, because finance outlives employment.';
COMMENT ON COLUMN "organizations"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "repositories" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning user. Exactly one of this and owner_org_id is set, which a check constraint enforces.
	"owner_user_id" BIGINT,
	-- Owning organisation. Null for a personal repository.
	"owner_org_id" BIGINT,
	-- Upstream repository this was forked from. Null for an original. Pull requests across forks depend on this link existing.
	"parent_repository_id" BIGINT,
	-- Repository name, unique within its owner rather than globally.
	"name" VARCHAR(100) NOT NULL,
	-- One-line summary shown in listings.
	"description" VARCHAR(400),
	-- Ref name treated as the trunk. Stored as a name rather than a foreign key because the branch can be deleted and recreated without the setting changing meaning.
	"default_branch" VARCHAR(255) NOT NULL DEFAULT 'main',
	-- public | private | internal.
	"visibility" VARCHAR(12) NOT NULL DEFAULT 'private',
	-- Read-only mode. Kept distinct from deletion: archived repositories still serve every URL that ever pointed at them.
	"is_archived" BOOLEAN NOT NULL DEFAULT false,
	-- High-water mark for the shared issue and pull request number sequence. Incremented atomically; this is the one counter that makes per-repository numbering work.
	"issue_counter" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last push. Denormalised because sorting repositories by recent activity is the single most common listing query.
	"pushed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "repositories" IS 'A repository. The git object database itself is not modelled here: this table describes the metadata around a repository that a database is genuinely better at than a packfile.';
COMMENT ON COLUMN "repositories"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "repositories"."owner_user_id" IS 'Owning user. Exactly one of this and owner_org_id is set, which a check constraint enforces.';
COMMENT ON COLUMN "repositories"."owner_org_id" IS 'Owning organisation. Null for a personal repository.';
COMMENT ON COLUMN "repositories"."parent_repository_id" IS 'Upstream repository this was forked from. Null for an original. Pull requests across forks depend on this link existing.';
COMMENT ON COLUMN "repositories"."name" IS 'Repository name, unique within its owner rather than globally.';
COMMENT ON COLUMN "repositories"."description" IS 'One-line summary shown in listings.';
COMMENT ON COLUMN "repositories"."default_branch" IS 'Ref name treated as the trunk. Stored as a name rather than a foreign key because the branch can be deleted and recreated without the setting changing meaning.';
COMMENT ON COLUMN "repositories"."visibility" IS 'public | private | internal.';
COMMENT ON COLUMN "repositories"."is_archived" IS 'Read-only mode. Kept distinct from deletion: archived repositories still serve every URL that ever pointed at them.';
COMMENT ON COLUMN "repositories"."issue_counter" IS 'High-water mark for the shared issue and pull request number sequence. Incremented atomically; this is the one counter that makes per-repository numbering work.';
COMMENT ON COLUMN "repositories"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "repositories"."pushed_at" IS 'Last push. Denormalised because sorting repositories by recent activity is the single most common listing query.';

CREATE UNIQUE INDEX "uq_repositories_user_name"
ON "repositories" ("owner_user_id", "name");
CREATE UNIQUE INDEX "uq_repositories_org_name"
ON "repositories" ("owner_org_id", "name");
CREATE INDEX "idx_repositories_visibility_pushed"
ON "repositories" ("visibility", "pushed_at");

CREATE TABLE IF NOT EXISTS "git_refs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Repository the ref lives in.
	"repository_id" BIGINT NOT NULL,
	-- Fully qualified ref name, e.g. refs/heads/main or refs/tags/v2.1.0. Storing the prefix rather than a type column keeps the table honest about what git actually has.
	"name" VARCHAR(255) NOT NULL,
	-- Commit the ref currently points at. A 40-character hex SHA-1, fixed width, so CHAR is the right type for once.
	"target_sha" CHAR(40) NOT NULL,
	-- branch | tag. Derivable from the name prefix, denormalised because every branch picker filters on it.
	"ref_type" VARCHAR(12) NOT NULL DEFAULT 'branch',
	-- Whether force-push and deletion are blocked. The rules themselves live in a branch protection service; this is the flag the push path checks.
	"is_protected" BOOLEAN NOT NULL DEFAULT false,
	-- Last time the ref moved. This is what a push actually changes.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "git_refs" IS 'A mutable pointer into the commit graph. Refs move constantly, which is exactly why nothing else in this schema stores a branch name as a foreign key.';
COMMENT ON COLUMN "git_refs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "git_refs"."repository_id" IS 'Repository the ref lives in.';
COMMENT ON COLUMN "git_refs"."name" IS 'Fully qualified ref name, e.g. refs/heads/main or refs/tags/v2.1.0. Storing the prefix rather than a type column keeps the table honest about what git actually has.';
COMMENT ON COLUMN "git_refs"."target_sha" IS 'Commit the ref currently points at. A 40-character hex SHA-1, fixed width, so CHAR is the right type for once.';
COMMENT ON COLUMN "git_refs"."ref_type" IS 'branch | tag. Derivable from the name prefix, denormalised because every branch picker filters on it.';
COMMENT ON COLUMN "git_refs"."is_protected" IS 'Whether force-push and deletion are blocked. The rules themselves live in a branch protection service; this is the flag the push path checks.';
COMMENT ON COLUMN "git_refs"."updated_at" IS 'Last time the ref moved. This is what a push actually changes.';

CREATE UNIQUE INDEX "uq_git_refs_repo_name"
ON "git_refs" ("repository_id", "name");
CREATE INDEX "idx_git_refs_repo_type"
ON "git_refs" ("repository_id", "ref_type");

CREATE TABLE IF NOT EXISTS "commits" (
	-- Surrogate primary key. The SHA is the natural key, but a narrow integer is cheaper to join on a table this large.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Repository the commit was indexed for. The same SHA appears once per repository, because a fork genuinely has its own copy in the metadata layer.
	"repository_id" BIGINT NOT NULL,
	-- Commit SHA-1.
	"sha" CHAR(40) NOT NULL,
	-- Space-separated parent SHAs. Two for a merge, none for a root commit. Denormalised rather than an edge table because the graph is walked in git, not in SQL.
	"parent_shas" VARCHAR(500),
	-- Matched account. Null when the commit email belongs to nobody here, which is common and must not block indexing.
	"author_user_id" BIGINT,
	-- Name from the commit object. Snapshotted because git recorded it and it can never be corrected retroactively.
	"author_name" VARCHAR(160) NOT NULL,
	-- Email from the commit object, which is how author_user_id is resolved.
	"author_email" VARCHAR(320) NOT NULL,
	-- Full commit message, subject and body.
	"message" TEXT NOT NULL,
	-- When the change was written.
	"authored_at" TIMESTAMP NOT NULL,
	-- When the commit object was created. Differs from authored_at after a rebase or a cherry-pick, which is the only reason both exist.
	"committed_at" TIMESTAMP NOT NULL,
	-- Lines added, computed at index time. Null until the diff has been walked.
	"additions" INTEGER,
	-- Lines removed, same.
	"deletions" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "commits" IS 'An indexed commit. It is a cache of what git already knows, kept in SQL so that blame, contribution graphs and pull request timelines do not have to shell out to a packfile.';
COMMENT ON COLUMN "commits"."id" IS 'Surrogate primary key. The SHA is the natural key, but a narrow integer is cheaper to join on a table this large.';
COMMENT ON COLUMN "commits"."repository_id" IS 'Repository the commit was indexed for. The same SHA appears once per repository, because a fork genuinely has its own copy in the metadata layer.';
COMMENT ON COLUMN "commits"."sha" IS 'Commit SHA-1.';
COMMENT ON COLUMN "commits"."parent_shas" IS 'Space-separated parent SHAs. Two for a merge, none for a root commit. Denormalised rather than an edge table because the graph is walked in git, not in SQL.';
COMMENT ON COLUMN "commits"."author_user_id" IS 'Matched account. Null when the commit email belongs to nobody here, which is common and must not block indexing.';
COMMENT ON COLUMN "commits"."author_name" IS 'Name from the commit object. Snapshotted because git recorded it and it can never be corrected retroactively.';
COMMENT ON COLUMN "commits"."author_email" IS 'Email from the commit object, which is how author_user_id is resolved.';
COMMENT ON COLUMN "commits"."message" IS 'Full commit message, subject and body.';
COMMENT ON COLUMN "commits"."authored_at" IS 'When the change was written.';
COMMENT ON COLUMN "commits"."committed_at" IS 'When the commit object was created. Differs from authored_at after a rebase or a cherry-pick, which is the only reason both exist.';
COMMENT ON COLUMN "commits"."additions" IS 'Lines added, computed at index time. Null until the diff has been walked.';
COMMENT ON COLUMN "commits"."deletions" IS 'Lines removed, same.';

CREATE UNIQUE INDEX "uq_commits_repo_sha"
ON "commits" ("repository_id", "sha");
CREATE INDEX "idx_commits_author_committed"
ON "commits" ("author_user_id", "committed_at");

CREATE TABLE IF NOT EXISTS "milestones" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Repository the milestone belongs to.
	"repository_id" BIGINT NOT NULL,
	-- Per-repository milestone number, its own sequence separate from the issue one.
	"number" INTEGER NOT NULL,
	-- Milestone name, e.g. v3.0.
	"title" VARCHAR(200) NOT NULL,
	-- What the milestone covers.
	"description" TEXT,
	-- open | closed.
	"state" VARCHAR(12) NOT NULL DEFAULT 'open',
	-- Target date. A DATE, not a timestamp: a deadline is a day, and a timezone-converted deadline slips by one twice a year.
	"due_on" DATE,
	-- When it was closed.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "milestones" IS 'A dated bucket of work. Issues point at it rather than the other way round, so a milestone can be reassigned wholesale without touching the issues.';
COMMENT ON COLUMN "milestones"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "milestones"."repository_id" IS 'Repository the milestone belongs to.';
COMMENT ON COLUMN "milestones"."number" IS 'Per-repository milestone number, its own sequence separate from the issue one.';
COMMENT ON COLUMN "milestones"."title" IS 'Milestone name, e.g. v3.0.';
COMMENT ON COLUMN "milestones"."description" IS 'What the milestone covers.';
COMMENT ON COLUMN "milestones"."state" IS 'open | closed.';
COMMENT ON COLUMN "milestones"."due_on" IS 'Target date. A DATE, not a timestamp: a deadline is a day, and a timezone-converted deadline slips by one twice a year.';
COMMENT ON COLUMN "milestones"."closed_at" IS 'When it was closed.';

CREATE UNIQUE INDEX "uq_milestones_repo_number"
ON "milestones" ("repository_id", "number");

CREATE TABLE IF NOT EXISTS "issues" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Repository this belongs to.
	"repository_id" BIGINT NOT NULL,
	-- The number people type after a hash. Allocated from repositories.issue_counter and shared with pull requests, which is why #12 is never both an issue and a pull request.
	"number" INTEGER NOT NULL,
	-- Whether a pull_requests row extends this one. Denormalised so the issue list can filter without a join to a table most rows have no match in.
	"is_pull_request" BOOLEAN NOT NULL DEFAULT false,
	-- Who opened it. Null when the account has been purged, which must not delete the discussion.
	"author_id" BIGINT,
	-- Milestone assigned. Null for unplanned work.
	"milestone_id" BIGINT,
	-- Subject line.
	"title" VARCHAR(400) NOT NULL,
	-- Opening comment in Markdown. Null for an issue created from a template with nothing filled in.
	"body" TEXT,
	-- open | closed.
	"state" VARCHAR(12) NOT NULL DEFAULT 'open',
	-- completed | not_planned | reopened | merged. Closed alone does not distinguish shipped from abandoned, and every triage report needs that difference.
	"state_reason" VARCHAR(20),
	-- Denormalised count for list rendering. Recomputed rather than trusted during repair jobs.
	"comment_count" INTEGER NOT NULL DEFAULT 0,
	-- When it was opened.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last activity, which drives the default sort.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When it was closed. Reopening clears it rather than adding a row, with the history living in a timeline service.
	"closed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "issues" IS 'The base record for both issues and pull requests. Merging them is not a convenience: they share one number sequence, one comment stream, one label set and one assignee model, and splitting them means duplicating all four.';
COMMENT ON COLUMN "issues"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "issues"."repository_id" IS 'Repository this belongs to.';
COMMENT ON COLUMN "issues"."number" IS 'The number people type after a hash. Allocated from repositories.issue_counter and shared with pull requests, which is why #12 is never both an issue and a pull request.';
COMMENT ON COLUMN "issues"."is_pull_request" IS 'Whether a pull_requests row extends this one. Denormalised so the issue list can filter without a join to a table most rows have no match in.';
COMMENT ON COLUMN "issues"."author_id" IS 'Who opened it. Null when the account has been purged, which must not delete the discussion.';
COMMENT ON COLUMN "issues"."milestone_id" IS 'Milestone assigned. Null for unplanned work.';
COMMENT ON COLUMN "issues"."title" IS 'Subject line.';
COMMENT ON COLUMN "issues"."body" IS 'Opening comment in Markdown. Null for an issue created from a template with nothing filled in.';
COMMENT ON COLUMN "issues"."state" IS 'open | closed.';
COMMENT ON COLUMN "issues"."state_reason" IS 'completed | not_planned | reopened | merged. Closed alone does not distinguish shipped from abandoned, and every triage report needs that difference.';
COMMENT ON COLUMN "issues"."comment_count" IS 'Denormalised count for list rendering. Recomputed rather than trusted during repair jobs.';
COMMENT ON COLUMN "issues"."created_at" IS 'When it was opened.';
COMMENT ON COLUMN "issues"."updated_at" IS 'Last activity, which drives the default sort.';
COMMENT ON COLUMN "issues"."closed_at" IS 'When it was closed. Reopening clears it rather than adding a row, with the history living in a timeline service.';

CREATE UNIQUE INDEX "uq_issues_repo_number"
ON "issues" ("repository_id", "number");
CREATE INDEX "idx_issues_repo_state_updated"
ON "issues" ("repository_id", "state", "updated_at");
CREATE INDEX "idx_issues_author_created"
ON "issues" ("author_id", "created_at");

CREATE TABLE IF NOT EXISTS "pull_requests" (
	-- Primary key and foreign key at once. A pull request is an issue with extra columns, so it shares the issue identity rather than inventing a second one.
	"issue_id" BIGINT,
	-- Repository the source branch lives in. Differs from the base repository for a fork, and goes null when the fork is deleted, which is exactly when a stale pull request becomes unmergeable.
	"head_repository_id" BIGINT,
	-- Source branch name as text. Not a foreign key to git_refs, because the branch is routinely deleted after merge and the pull request must still describe itself.
	"head_ref_name" VARCHAR(255) NOT NULL,
	-- Tip commit of the source branch right now. Updated on every push, and the value review comments are anchored against.
	"head_sha" CHAR(40) NOT NULL,
	-- Target branch name, e.g. main.
	"base_ref_name" VARCHAR(255) NOT NULL,
	-- Commit the diff is computed from. Moves when the base branch advances, which is what silently makes old review comments outdated.
	"base_sha" CHAR(40) NOT NULL,
	-- Resulting commit. Null until merged, and null forever for a closed-without-merge pull request.
	"merge_commit_sha" CHAR(40),
	-- Who pressed merge. Often not the author, and often the most interesting name on the whole record.
	"merged_by_id" BIGINT,
	-- merge | squash | rebase. Stored because it determines whether the head commits exist on the base branch afterwards.
	"merge_method" VARCHAR(12),
	-- Draft state. Blocks merging and suppresses review requests.
	"is_draft" BOOLEAN NOT NULL DEFAULT false,
	-- File count in the diff, cached for the header. Recomputed on every push to the head.
	"changed_files" INTEGER,
	-- Merge time. Its presence, not the issue state, is the definition of merged.
	"merged_at" TIMESTAMP,
	PRIMARY KEY("issue_id")
);

COMMENT ON TABLE "pull_requests" IS 'The code-specific half of a pull request. Branch names are stored as text on purpose: refs are deleted after merge, and a pull request has to keep rendering for years afterwards.';
COMMENT ON COLUMN "pull_requests"."issue_id" IS 'Primary key and foreign key at once. A pull request is an issue with extra columns, so it shares the issue identity rather than inventing a second one.';
COMMENT ON COLUMN "pull_requests"."head_repository_id" IS 'Repository the source branch lives in. Differs from the base repository for a fork, and goes null when the fork is deleted, which is exactly when a stale pull request becomes unmergeable.';
COMMENT ON COLUMN "pull_requests"."head_ref_name" IS 'Source branch name as text. Not a foreign key to git_refs, because the branch is routinely deleted after merge and the pull request must still describe itself.';
COMMENT ON COLUMN "pull_requests"."head_sha" IS 'Tip commit of the source branch right now. Updated on every push, and the value review comments are anchored against.';
COMMENT ON COLUMN "pull_requests"."base_ref_name" IS 'Target branch name, e.g. main.';
COMMENT ON COLUMN "pull_requests"."base_sha" IS 'Commit the diff is computed from. Moves when the base branch advances, which is what silently makes old review comments outdated.';
COMMENT ON COLUMN "pull_requests"."merge_commit_sha" IS 'Resulting commit. Null until merged, and null forever for a closed-without-merge pull request.';
COMMENT ON COLUMN "pull_requests"."merged_by_id" IS 'Who pressed merge. Often not the author, and often the most interesting name on the whole record.';
COMMENT ON COLUMN "pull_requests"."merge_method" IS 'merge | squash | rebase. Stored because it determines whether the head commits exist on the base branch afterwards.';
COMMENT ON COLUMN "pull_requests"."is_draft" IS 'Draft state. Blocks merging and suppresses review requests.';
COMMENT ON COLUMN "pull_requests"."changed_files" IS 'File count in the diff, cached for the header. Recomputed on every push to the head.';
COMMENT ON COLUMN "pull_requests"."merged_at" IS 'Merge time. Its presence, not the issue state, is the definition of merged.';

CREATE INDEX "idx_pull_requests_head"
ON "pull_requests" ("head_repository_id", "head_ref_name");
CREATE INDEX "idx_pull_requests_merged_at"
ON "pull_requests" ("merged_at");

CREATE TABLE IF NOT EXISTS "labels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning repository. Labels are per-repository, which is why the same bug label is a different row in every project.
	"repository_id" BIGINT NOT NULL,
	-- Label text. Renaming it must update every issue that shows it, which is the argument for the join table below carrying an id rather than the string.
	"name" VARCHAR(80) NOT NULL,
	-- Six-digit hex without the hash, as the API returns it.
	"color" CHAR(6) NOT NULL DEFAULT 'ededed',
	-- Tooltip explaining what the label means, which is the only thing that stops a label set rotting.
	"description" VARCHAR(200),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "labels" IS 'A per-repository tag. Trivial as a table, and the reason issue triage works at all; the interesting constraint is that the name is unique per repository, not globally.';
COMMENT ON COLUMN "labels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "labels"."repository_id" IS 'Owning repository. Labels are per-repository, which is why the same bug label is a different row in every project.';
COMMENT ON COLUMN "labels"."name" IS 'Label text. Renaming it must update every issue that shows it, which is the argument for the join table below carrying an id rather than the string.';
COMMENT ON COLUMN "labels"."color" IS 'Six-digit hex without the hash, as the API returns it.';
COMMENT ON COLUMN "labels"."description" IS 'Tooltip explaining what the label means, which is the only thing that stops a label set rotting.';

CREATE UNIQUE INDEX "uq_labels_repo_name"
ON "labels" ("repository_id", "name");

CREATE TABLE IF NOT EXISTS "issue_labels" (
	-- Issue being labelled. Half of the composite key; a join table has no business carrying a surrogate id.
	"issue_id" BIGINT,
	-- Label applied.
	"label_id" BIGINT,
	-- When it was added. Enough to answer how long something sat as needs-triage, without a full event log.
	"applied_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("issue_id", "label_id")
);

COMMENT ON TABLE "issue_labels" IS 'The many-to-many between issues and labels. It covers pull requests too, for free, because a pull request is an issue.';
COMMENT ON COLUMN "issue_labels"."issue_id" IS 'Issue being labelled. Half of the composite key; a join table has no business carrying a surrogate id.';
COMMENT ON COLUMN "issue_labels"."label_id" IS 'Label applied.';
COMMENT ON COLUMN "issue_labels"."applied_at" IS 'When it was added. Enough to answer how long something sat as needs-triage, without a full event log.';

CREATE TABLE IF NOT EXISTS "reviews" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Pull request being reviewed.
	"pull_request_id" BIGINT NOT NULL,
	-- Who reviewed.
	"reviewer_id" BIGINT NOT NULL,
	-- Head commit the reviewer actually looked at. This is what makes an approval auditable: approving a diff is not approving whatever gets pushed next.
	"commit_sha" CHAR(40) NOT NULL,
	-- pending | commented | approved | changes_requested | dismissed.
	"state" VARCHAR(20) NOT NULL,
	-- Summary comment submitted with the review. Null for a review that is only line comments.
	"body" TEXT,
	-- When the review was published. Null while it is still a pending draft visible only to its author.
	"submitted_at" TIMESTAMP,
	-- When an approval was invalidated, by a push or by a maintainer. The row stays, because an approval that was later dismissed is part of the history.
	"dismissed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "reviews" IS 'One submitted verdict on one pull request at one commit. The commit SHA is the whole reason this is not a boolean on the pull request: approvals go stale the moment the branch moves.';
COMMENT ON COLUMN "reviews"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "reviews"."pull_request_id" IS 'Pull request being reviewed.';
COMMENT ON COLUMN "reviews"."reviewer_id" IS 'Who reviewed.';
COMMENT ON COLUMN "reviews"."commit_sha" IS 'Head commit the reviewer actually looked at. This is what makes an approval auditable: approving a diff is not approving whatever gets pushed next.';
COMMENT ON COLUMN "reviews"."state" IS 'pending | commented | approved | changes_requested | dismissed.';
COMMENT ON COLUMN "reviews"."body" IS 'Summary comment submitted with the review. Null for a review that is only line comments.';
COMMENT ON COLUMN "reviews"."submitted_at" IS 'When the review was published. Null while it is still a pending draft visible only to its author.';
COMMENT ON COLUMN "reviews"."dismissed_at" IS 'When an approval was invalidated, by a push or by a maintainer. The row stays, because an approval that was later dismissed is part of the history.';

CREATE INDEX "idx_reviews_pr_submitted"
ON "reviews" ("pull_request_id", "submitted_at");
CREATE INDEX "idx_reviews_reviewer_state"
ON "reviews" ("reviewer_id", "state");

CREATE TABLE IF NOT EXISTS "review_comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Pull request the comment lives on. Denormalised from the review so the conversation loads without a join.
	"pull_request_id" BIGINT NOT NULL,
	-- Review it was submitted with. Null for a single comment posted outside a formal review.
	"review_id" BIGINT,
	-- Parent comment. A non-null value makes this part of an existing thread rather than a new one, which is the entire threading model.
	"in_reply_to_id" BIGINT,
	-- Who wrote it. Null for a purged account.
	"author_id" BIGINT,
	-- File path the comment is anchored to, relative to the repository root. If the file is renamed later the anchor is lost, which is why an outdated flag exists.
	"path" VARCHAR(1000) NOT NULL,
	-- Commit the comment is currently anchored to, updated as the pull request is rebased and the anchor is successfully carried forward.
	"commit_sha" CHAR(40) NOT NULL,
	-- Commit the comment was first written against. Never changes. Without it you cannot reconstruct the code the reviewer was actually looking at.
	"original_commit_sha" CHAR(40) NOT NULL,
	-- LEFT | RIGHT. Which half of the split diff. A comment on a deleted line is on LEFT, and confusing the two puts the comment on the wrong version of the file.
	"diff_side" VARCHAR(6) NOT NULL DEFAULT 'RIGHT',
	-- Line number in the current diff, on diff_side. Null once the comment has drifted off the diff entirely.
	"line" INTEGER,
	-- First line of a multi-line comment. Null for a single-line comment, which is the overwhelming majority.
	"start_line" INTEGER,
	-- Line number in the original commit. This is the stable anchor: line moves as the branch changes, original_line never does.
	"original_line" INTEGER NOT NULL,
	-- The few lines of diff context captured when the comment was written. This is what actually renders an outdated comment, because the code it refers to may no longer exist anywhere.
	"diff_hunk" TEXT NOT NULL,
	-- True once the anchored lines no longer appear in the current diff. The comment is still shown, collapsed, with its captured hunk.
	"is_outdated" BOOLEAN NOT NULL DEFAULT false,
	-- Thread resolution, set on the first comment of a thread and read for the whole chain.
	"is_resolved" BOOLEAN NOT NULL DEFAULT false,
	-- Comment text in Markdown.
	"body" TEXT NOT NULL,
	-- When it was written.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Last edit.
	"updated_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "review_comments" IS 'A comment nailed to a file and a line. The anchor is four columns, not one, because the only durable part of it is the original commit and line; everything else is a best-effort attempt to keep the comment next to the code as the branch moves under it.';
COMMENT ON COLUMN "review_comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "review_comments"."pull_request_id" IS 'Pull request the comment lives on. Denormalised from the review so the conversation loads without a join.';
COMMENT ON COLUMN "review_comments"."review_id" IS 'Review it was submitted with. Null for a single comment posted outside a formal review.';
COMMENT ON COLUMN "review_comments"."in_reply_to_id" IS 'Parent comment. A non-null value makes this part of an existing thread rather than a new one, which is the entire threading model.';
COMMENT ON COLUMN "review_comments"."author_id" IS 'Who wrote it. Null for a purged account.';
COMMENT ON COLUMN "review_comments"."path" IS 'File path the comment is anchored to, relative to the repository root. If the file is renamed later the anchor is lost, which is why an outdated flag exists.';
COMMENT ON COLUMN "review_comments"."commit_sha" IS 'Commit the comment is currently anchored to, updated as the pull request is rebased and the anchor is successfully carried forward.';
COMMENT ON COLUMN "review_comments"."original_commit_sha" IS 'Commit the comment was first written against. Never changes. Without it you cannot reconstruct the code the reviewer was actually looking at.';
COMMENT ON COLUMN "review_comments"."diff_side" IS 'LEFT | RIGHT. Which half of the split diff. A comment on a deleted line is on LEFT, and confusing the two puts the comment on the wrong version of the file.';
COMMENT ON COLUMN "review_comments"."line" IS 'Line number in the current diff, on diff_side. Null once the comment has drifted off the diff entirely.';
COMMENT ON COLUMN "review_comments"."start_line" IS 'First line of a multi-line comment. Null for a single-line comment, which is the overwhelming majority.';
COMMENT ON COLUMN "review_comments"."original_line" IS 'Line number in the original commit. This is the stable anchor: line moves as the branch changes, original_line never does.';
COMMENT ON COLUMN "review_comments"."diff_hunk" IS 'The few lines of diff context captured when the comment was written. This is what actually renders an outdated comment, because the code it refers to may no longer exist anywhere.';
COMMENT ON COLUMN "review_comments"."is_outdated" IS 'True once the anchored lines no longer appear in the current diff. The comment is still shown, collapsed, with its captured hunk.';
COMMENT ON COLUMN "review_comments"."is_resolved" IS 'Thread resolution, set on the first comment of a thread and read for the whole chain.';
COMMENT ON COLUMN "review_comments"."body" IS 'Comment text in Markdown.';
COMMENT ON COLUMN "review_comments"."created_at" IS 'When it was written.';
COMMENT ON COLUMN "review_comments"."updated_at" IS 'Last edit.';

CREATE INDEX "idx_review_comments_anchor"
ON "review_comments" ("pull_request_id", "path", "original_line");
CREATE INDEX "idx_review_comments_thread"
ON "review_comments" ("in_reply_to_id");
CREATE INDEX "idx_review_comments_review"
ON "review_comments" ("review_id");

CREATE TABLE IF NOT EXISTS "workflow_runs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Repository the workflow lives in.
	"repository_id" BIGINT NOT NULL,
	-- Who caused it. Null for a schedule or a bot push, which is a meaningful distinction when a run does something destructive.
	"triggering_user_id" BIGINT,
	-- Path of the workflow file, e.g. .github/workflows/ci.yml. A path rather than a foreign key, because the file is versioned in git and may not exist on the default branch.
	"workflow_path" VARCHAR(400) NOT NULL,
	-- Per-workflow counter shown in the UI. Distinct from run_attempt: the number identifies the run, the attempt identifies the try.
	"run_number" INTEGER NOT NULL,
	-- Retry counter. Re-running a failed workflow increments this in place rather than creating a new run, which is why job rows carry it too.
	"run_attempt" INTEGER NOT NULL DEFAULT 1,
	-- What triggered it: push | pull_request | schedule | workflow_dispatch | release.
	"event" VARCHAR(40) NOT NULL,
	-- Commit the run was built from. The single most important column here: a green tick means nothing without knowing which commit it was green for.
	"head_sha" CHAR(40) NOT NULL,
	-- Branch name at trigger time. Null for a tag or a detached run.
	"head_branch" VARCHAR(255),
	-- queued | in_progress | completed.
	"status" VARCHAR(20) NOT NULL DEFAULT 'queued',
	-- success | failure | cancelled | skipped | timed_out. Null until status is completed, which is why the two columns are separate.
	"conclusion" VARCHAR(20),
	-- When the first job picked up work. Null while still queued, and queue time is started_at minus created_at.
	"started_at" TIMESTAMP,
	-- When the last job finished.
	"completed_at" TIMESTAMP,
	-- When the trigger fired.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "workflow_runs" IS 'One execution of one workflow file against one commit. Status and conclusion are deliberately two columns: a run that is still going has no conclusion, and collapsing them makes every dashboard query guess.';
COMMENT ON COLUMN "workflow_runs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "workflow_runs"."repository_id" IS 'Repository the workflow lives in.';
COMMENT ON COLUMN "workflow_runs"."triggering_user_id" IS 'Who caused it. Null for a schedule or a bot push, which is a meaningful distinction when a run does something destructive.';
COMMENT ON COLUMN "workflow_runs"."workflow_path" IS 'Path of the workflow file, e.g. .github/workflows/ci.yml. A path rather than a foreign key, because the file is versioned in git and may not exist on the default branch.';
COMMENT ON COLUMN "workflow_runs"."run_number" IS 'Per-workflow counter shown in the UI. Distinct from run_attempt: the number identifies the run, the attempt identifies the try.';
COMMENT ON COLUMN "workflow_runs"."run_attempt" IS 'Retry counter. Re-running a failed workflow increments this in place rather than creating a new run, which is why job rows carry it too.';
COMMENT ON COLUMN "workflow_runs"."event" IS 'What triggered it: push | pull_request | schedule | workflow_dispatch | release.';
COMMENT ON COLUMN "workflow_runs"."head_sha" IS 'Commit the run was built from. The single most important column here: a green tick means nothing without knowing which commit it was green for.';
COMMENT ON COLUMN "workflow_runs"."head_branch" IS 'Branch name at trigger time. Null for a tag or a detached run.';
COMMENT ON COLUMN "workflow_runs"."status" IS 'queued | in_progress | completed.';
COMMENT ON COLUMN "workflow_runs"."conclusion" IS 'success | failure | cancelled | skipped | timed_out. Null until status is completed, which is why the two columns are separate.';
COMMENT ON COLUMN "workflow_runs"."started_at" IS 'When the first job picked up work. Null while still queued, and queue time is started_at minus created_at.';
COMMENT ON COLUMN "workflow_runs"."completed_at" IS 'When the last job finished.';
COMMENT ON COLUMN "workflow_runs"."created_at" IS 'When the trigger fired.';

CREATE INDEX "idx_workflow_runs_repo_created"
ON "workflow_runs" ("repository_id", "created_at");
CREATE INDEX "idx_workflow_runs_head_sha"
ON "workflow_runs" ("head_sha");
CREATE INDEX "idx_workflow_runs_status_conclusion"
ON "workflow_runs" ("status", "conclusion");

CREATE TABLE IF NOT EXISTS "workflow_jobs" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent run.
	"run_id" BIGINT NOT NULL,
	-- Job name from the workflow file, matrix values already expanded, e.g. test (ubuntu-latest, 20).
	"name" VARCHAR(200) NOT NULL,
	-- Attempt this job belongs to. A re-run creates new job rows against the same run, so the previous attempt logs stay reachable.
	"run_attempt" INTEGER NOT NULL DEFAULT 1,
	-- queued | in_progress | completed.
	"status" VARCHAR(20) NOT NULL DEFAULT 'queued',
	-- success | failure | cancelled | skipped. Null until completed.
	"conclusion" VARCHAR(20),
	-- Machine that executed it. Null while queued, and the first thing anyone looks at when one matrix leg is mysteriously slow.
	"runner_name" VARCHAR(120),
	-- Labels the job requested, e.g. ubuntu-latest or self-hosted,gpu. Snapshotted because the runner pool changes shape constantly.
	"runner_labels" VARCHAR(300),
	-- Pickup time.
	"started_at" TIMESTAMP,
	-- Finish time.
	"completed_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "workflow_jobs" IS 'A single job within a run, one row per matrix leg per attempt. Keeping failed attempts rather than overwriting them is what makes a flaky test visible instead of merely annoying.';
COMMENT ON COLUMN "workflow_jobs"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "workflow_jobs"."run_id" IS 'Parent run.';
COMMENT ON COLUMN "workflow_jobs"."name" IS 'Job name from the workflow file, matrix values already expanded, e.g. test (ubuntu-latest, 20).';
COMMENT ON COLUMN "workflow_jobs"."run_attempt" IS 'Attempt this job belongs to. A re-run creates new job rows against the same run, so the previous attempt logs stay reachable.';
COMMENT ON COLUMN "workflow_jobs"."status" IS 'queued | in_progress | completed.';
COMMENT ON COLUMN "workflow_jobs"."conclusion" IS 'success | failure | cancelled | skipped. Null until completed.';
COMMENT ON COLUMN "workflow_jobs"."runner_name" IS 'Machine that executed it. Null while queued, and the first thing anyone looks at when one matrix leg is mysteriously slow.';
COMMENT ON COLUMN "workflow_jobs"."runner_labels" IS 'Labels the job requested, e.g. ubuntu-latest or self-hosted,gpu. Snapshotted because the runner pool changes shape constantly.';
COMMENT ON COLUMN "workflow_jobs"."started_at" IS 'Pickup time.';
COMMENT ON COLUMN "workflow_jobs"."completed_at" IS 'Finish time.';

CREATE INDEX "idx_workflow_jobs_run_attempt"
ON "workflow_jobs" ("run_id", "run_attempt");
CREATE INDEX "idx_workflow_jobs_conclusion_completed"
ON "workflow_jobs" ("conclusion", "completed_at");

